function HeroCarousel() {
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);

  useEffect(() => {
    if (
      paused ||
      hovered ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    )
      return;
    const timer = window.setInterval(() => {
      setActive((current) => (current + 1) % heroSlides.length);
    }, 6500);
    return () => window.clearInterval(timer);
  }, [paused, hovered]);

  function move(direction: number) {
    setActive(
      (current) =>
        (current + direction + heroSlides.length) % heroSlides.length,
    );
  }

  const slide = heroSlides[active];
  return (
    <section
      className={`lp-carousel lp-hero-carousel-background${paused || hovered ? " is-paused" : ""}`}
      aria-label="OrderMesh in everyday business"
      aria-roledescription="carousel"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <div className="lp-carousel-frame">
        {heroSlides.map((item, index) => (
          <Image
            key={item.image}
            src={item.image}
            alt={item.alt}
            aria-hidden={active !== index}
            fill
            priority={index === 0}
            sizes="(max-width: 1000px) 100vw, 50vw"
            className={`lp-carousel-image${active === index ? " active" : ""}`}
          />
        ))}
        <div className="lp-carousel-shade" />
        <div className="lp-carousel-topline">
          <span className="lp-carousel-orbit">
            <Layers3 size={14} />
          </span>
          <span>ORDERMESH AI</span>
          <span className="lp-carousel-visual-tag">
            BRAND VISUALS · NOT LIVE DATA
          </span>
        </div>
        <div className="lp-carousel-signal" key={`signal-${active}`}>
          <span>
            <Sparkles size={15} />
          </span>
          <div>
            <small>CONNECTED WORKSPACE</small>
            <strong>{slide.signal}</strong>
          </div>
          <i />
        </div>
        <div className="lp-carousel-caption" key={`caption-${active}`}>
          <span className="lp-carousel-eyebrow">
            <span />
            {slide.eyebrow}
          </span>
          <h2>{slide.title}</h2>
          <p>{slide.detail}</p>
        </div>
        <div className="lp-carousel-controls">
          <div className="lp-carousel-arrows">
            <button
              type="button"
              aria-label="Previous slide"
              onClick={() => move(-1)}
            >
              <ChevronLeft size={18} />
            </button>
            <button
              type="button"
              aria-label="Next slide"
              onClick={() => move(1)}
            >
              <ChevronRight size={18} />
            </button>
          </div>
          <div
            className="lp-carousel-dots"
            role="group"
            aria-label="Choose carousel slide"
          >
            {heroSlides.map((item, index) => (
              <button
                key={item.eyebrow}
                type="button"
                aria-label={`Show slide ${index + 1}: ${item.eyebrow.toLowerCase()}`}
                aria-pressed={active === index}
                onClick={() => setActive(index)}
              >
                <span />
              </button>
            ))}
          </div>
          <button
            type="button"
            className="lp-carousel-toggle"
            aria-label={paused ? "Play slides" : "Pause slides"}
            onClick={() => setPaused((current) => !current)}
          >
            {paused ? <Play size={14} /> : <Pause size={14} />}
          </button>
        </div>
      </div>
      <span className="lp-carousel-count" aria-live="polite">
        0{active + 1} <i /> 0{heroSlides.length}
      </span>
    </section>
  );
}

